// ─────────────────────────────────────────────────────────────
// Node Code n8n : génère le prompt d'extraction (n° de facture + désignation + montant HT)
// pour les factures Crédit du Maroc Leasing & Factoring.
// Input  : $json.text  (texte extrait du PDF)
// Output : body prêt pour le node HTTP Request (chat completions)
//
// Nouveautés :
//  - extraction du N° de facture (regex AVANT l'appel au modèle, injecté comme indicateur)
//  - indicateur de matching sur les montants HT connus
// ─────────────────────────────────────────────────────────────

const MODEL = "mistral-small-latest";

// Liste des montants HT connus (un par contrat). Ajouter ici les nouveaux contrats.
const MONTANTS_REFERENCE = [
  "2 749,55",
  "17 784,20",
  "3 653,26",
  "4 432,12",
];

// 1. Récupération du texte brut du PDF
const fullText = String($json.text ?? $input.first()?.json?.text ?? '');

if (!fullText.trim()) {
  throw new Error("Aucun texte trouvé dans l'input (champ 'text' vide).");
}

// 2. Isolation de la zone utile : de "N ° de facture" jusqu'à "Siège social"
const start = /N\s*°\s*de facture/i.exec(fullText);
const end = /Si[èe]ge social/i.exec(fullText);

let zone = fullText;
if (start) {
  zone = fullText.slice(start.index, end && end.index > start.index ? end.index : undefined);
}
const lines = zone
  .split('\n')
  .map(l => l.trim())
  .filter(Boolean);
zone = lines.join('\n');

// 3a. Détection du N° de facture (même ligne que "N ° de facture", chiffres uniquement).
//     [ \t\u00A0:]* au lieu de \s* pour ne pas sauter à la ligne suivante
//     (sinon on capturerait le "01" de la ligne d'article si le numéro manque).
const mFact = /N\s*°\s*de\s+facture[ \t\u00A0:]*([0-9]{5,})/i.exec(fullText);
const numeroFacture = mFact ? mFact[1] : null; // string : on conserve les zéros éventuels

// 3b. Détection de l'indicateur de matching sur le montant HT
const norm = s => String(s).replace(/[\s\u00A0\u202F]/g, '');
const refMap = new Map(MONTANTS_REFERENCE.map(m => [norm(m), m]));
const refKeys = [...refMap.keys()].sort((a, b) => b.length - a.length);

const detectes = new Map(); // montant (formaté) -> { ligne: bool, bloc: bool }
const marquer = (montant, source) => {
  const cur = detectes.get(montant) ?? { ligne: false, bloc: false };
  cur[source] = true;
  detectes.set(montant, cur);
};

lines.forEach((line, i) => {
  const idx = line.search(/Loyer du/i);
  if (idx >= 0) {
    const avant = norm(idx > 0 ? line.slice(0, idx) : (lines[i - 1] ?? ''));
    const hit = refKeys.find(k => avant.endsWith(k));
    if (hit) marquer(refMap.get(hit), 'ligne');
  }
  const exact = norm(line);
  if (refMap.has(exact)) marquer(refMap.get(exact), 'bloc');
});

const toNumber = m => norm(m).replace(',', '.');

let indicateur;
if (detectes.size > 0) {
  const details = [...detectes.entries()].map(([montant, src]) => {
    const where = [
      src.ligne ? "fin de la ligne collée avant 'Loyer du'" : null,
      src.bloc ? "ligne isolée du bloc final (Sous-Total)" : null,
    ].filter(Boolean).join(' + ');
    const fiabilite = src.ligne && src.bloc ? 'fiabilité maximale' : 'fiabilité bonne';
    return `  - "${montant}" soit ${toNumber(montant)} (trouvé : ${where} ; ${fiabilite})`;
  }).join('\n');

  indicateur = `INDICATEUR DE MATCHING MONTANT (calculé avant ton analyse, très fiable) :
Un montant de la liste des montants HT connus a été retrouvé dans cette facture :
${details}
Utilise ce montant comme montant HT de l'article correspondant, sauf contradiction évidente avec les contrôles (HT + TVA = Total).`;
} else {
  indicateur = `INDICATEUR DE MATCHING MONTANT : aucun montant de la liste des montants HT connus n'a été retrouvé automatiquement.
Extrais le montant HT avec les règles ci-dessous. Il peut s'agir d'un nouveau contrat.`;
}

const indicateurFacture = numeroFacture
  ? `INDICATEUR N° DE FACTURE (calculé avant ton analyse, très fiable) : "${numeroFacture}" a été trouvé juste après "N ° de facture". Utilise-le tel quel.`
  : `INDICATEUR N° DE FACTURE : aucun numéro n'a été détecté automatiquement. Cherche-le toi-même dans la zone : il suit le libellé "N ° de facture".`;

const listeRef = MONTANTS_REFERENCE.map(m => `  - ${m}`).join('\n');

// 4. Construction du prompt
const prompt = `Tu es un extracteur de données spécialisé dans les factures de location du Crédit du Maroc Leasing & Factoring (Maroc), obtenues par extraction de texte PDF.

Voici la zone de la facture qui contient le numéro de facture, la ou les lignes d'articles et les montants (texte brut, la mise en forme du tableau est cassée par l'extraction PDF) :
───────────────────────────────────
${zone}
───────────────────────────────────

Ta tâche : retourner le NUMÉRO DE FACTURE, puis le NOM de l'article (le bien loué) et son MONTANT HT.

${indicateurFacture}

MONTANTS HT CONNUS (un par contrat de leasing) :
${listeRef}

${indicateur}

STRUCTURE HABITUELLE DE LA ZONE
  1. une ligne "N ° de facture <numéro>" (le numéro est une suite de chiffres, ex: 26042718)
  2. une ligne d'article : un numéro d'ordre à 2 chiffres ("01", "02", ...) suivi du nom de l'article
  3. une ligne cassée qui colle ensemble, dans cet ordre : Total TTC, Montant TVA, taux de TVA (20), Montant HT, puis la période "Loyer du ... au ..."
     Exemple : "3 299,46549,91202 749,55Loyer du 05/10/2026 au 04/11/2026"
     = Total 3 299,46 + TVA 549,91 + taux 20 + HT 2 749,55
     ATTENTION : le taux "20" est collé au début du HT ("202 749,55"). Le HT a 4 ou 5 chiffres avant la virgule : le HT est "2 749,55" et non "202 749,55" ni "749,55". Le HT est toujours la fin de la ligne, juste avant "Loyer du".
  4. un bloc de fin avec les libellés "Sous-Total", "TVA", "Total", puis trois montants dans cet ordre : Total, TVA, Sous-Total (= montant HT)

RÈGLES POUR LE NUMÉRO DE FACTURE
  - Le numéro de facture est la suite de chiffres qui suit "N ° de facture" (sur la même ligne).
  - Retourne-le sous forme de chaîne de caractères, sans espace, en conservant les zéros initiaux éventuels.
  - Ne le confonds JAMAIS avec le numéro de contrat (ligne "N ° de contrat"), le numéro client, le numéro d'ordre "01"/"02", l'ICE, le RC, la patente ou l'identifiant fiscal.
  - S'il est introuvable, mets null.

RÈGLES POUR LA DÉSIGNATION
  - La désignation est le texte qui suit le numéro d'ordre ("01", "02", ...) sur la ligne d'article. Retire ce numéro d'ordre du résultat.
  - Conserve la désignation telle qu'écrite (marque, modèle, casse), sans la reformuler ni la traduire.
  - Si la désignation se poursuit sur la ligne suivante, avant la ligne des montants, concatène les deux lignes avec un espace.
  - Ne mets JAMAIS dans la désignation : la ligne "Loyer du ... au ...", les montants, les taux de TVA, les dates, les numéros de contrat ou de facture.

RÈGLES POUR LE MONTANT HT
  - Priorité 1 : si l'indicateur de matching ci-dessus donne un montant, c'est le montant HT.
  - Priorité 2 : sinon, le montant HT est le "Sous-Total" du bloc de fin, confirmé par la fin de la ligne collée avant "Loyer du".
  - Si le montant extrait ne figure pas dans la liste des montants connus, retourne-le quand même (nouveau contrat possible).
  - Les montants ont toujours exactement 2 décimales. Les espaces sont des séparateurs de milliers, la virgule est le séparateur décimal (ex: "2 749,55" = 2749.55).
  - Contrôles : HT + TVA = Total, et TVA = 20 % du HT (à quelques centimes près). Utilise-les pour séparer correctement les montants collés.
  - Ne confonds JAMAIS le montant HT avec le Total TTC ni avec le montant de TVA.
  - S'il y a plusieurs articles, associe à chacun son propre montant HT s'il est lisible ; sinon mets null.

AUTRES RÈGLES
  - S'il y a plusieurs lignes d'articles ("01", "02", ...), retourne-les toutes, dans l'ordre d'apparition.
  - "error" vaut false si au moins une désignation et son montant ont été extraits. Il vaut true (avec "articles" vide) si aucune désignation n'est identifiable.
  - N'invente jamais de valeur.

EXEMPLES (illustratifs, ne pas réutiliser ces valeurs)

Zone contenant "N ° de facture 26042718", puis "01 Moteur électrique en fonte ABB", puis "3 299,46549,91202 749,55Loyer du 05/10/2026 au 04/11/2026", puis en fin de zone les montants "3 299,46", "549,91", "2 749,55".
Sortie attendue :
{ "facture": "CDM LEASING", "numero_facture": "26042718", "articles": [ { "designation": "Moteur électrique en fonte ABB", "montant": 2749.55 } ], "error": false }

Zone contenant "N ° de facture 26051234", puis "01 HYUNDAI H100", puis "4 383,91730,65203 653,26Loyer du 05/10/2026 au 04/11/2026", puis en fin de zone les montants "4 383,91", "730,65", "3 653,26".
Sortie attendue :
{ "facture": "CDM LEASING", "numero_facture": "26051234", "articles": [ { "designation": "HYUNDAI H100", "montant": 3653.26 } ], "error": false }

Cas à 5 chiffres avant la virgule (exemple construit) : ligne collée "21 341,043 556,842017 784,20Loyer du 05/10/2026 au 04/11/2026"
= Total 21 341,04 + TVA 3 556,84 + taux 20 + HT 17 784,20.
Sortie attendue (désignation et n° fictifs) :
{ "facture": "CDM LEASING", "numero_facture": "<n° de facture>", "articles": [ { "designation": "<désignation de la ligne d'article>", "montant": 17784.20 } ], "error": false }

Retourne UNIQUEMENT ce JSON, sans texte avant ou après, sans balises markdown. "numero_facture" est une chaîne (ou null), "montant" est un nombre JSON (point décimal, sans espace) :
{
  "facture": "CDM LEASING",
  "numero_facture": "<numéro de facture>",
  "articles": [
    { "designation": "<nom de l'article>", "montant": <montant HT> }
  ],
  "error": <true|false>
}`;

// 5. Objet prêt pour le node HTTP Request
return {
  json: {
    model: MODEL,
    temperature: 0,
    response_format: { type: "json_object" },
    messages: [
      { role: "user", content: prompt }
    ]
  }
};

const items = $input.all();


function extraireJson(raw) {
  let cleaned = raw.trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // Fallback : le LLM a peut-être ajouté du texte autour du JSON
    // (explication, markdown, etc.) — on tente d'isoler le premier bloc {...}
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (e2) {
        throw new Error(`Parsing JSON impossible (fallback échoué): ${e2.message}`);
      }
    }
    throw new Error(`Parsing JSON impossible: ${e.message}`);
  }
}

function normaliserBc(numero) {
  if (typeof numero !== 'string') return null;
  let n = numero.trim().toUpperCase();
  if (!n.startsWith('BC')) n = 'BC' + n.replace(/^BC/i, '');
  return n;
}

const result = items.map((item, index) => {
  const json = item.json;
  let data;

  try {
    // Détection de la source des données selon la structure de l'item
    if (json.choices && Array.isArray(json.choices) && json.choices[0]?.message?.content !== undefined) {
      data = json.choices[0].message.content; // format chat completion
    } else {
      data = json.output ?? json;
    }

    if (typeof data === 'string') {
      data = extraireJson(data);
    }

    if (!data || typeof data !== 'object') {
      throw new Error('Structure de données inattendue après extraction');
    }

    const brut = Array.isArray(data.numeros_bc) ? data.numeros_bc : [];

    // Normalisation + déduplication (ordre préservé)
    const vus = new Set();
    const numerosNormalises = [];
    for (const num of brut) {
      const n = normaliserBc(num);
      if (n && !vus.has(n)) {
        vus.add(n);
        numerosNormalises.push(n);
      }
    }


    return {
      json: {
        ...data,
        error: false
      }
    };

  } catch (e) {
    return {
      json: {
        error: true,
        error_message: e.message,
        item_index: index,
        raw_output: typeof data !== 'undefined' ? data : json,
        statut_bc: 'ERREUR_PARSING'
      }
    };
  }
});

return result;

