function generateTimestamp() {
  const now = new Date();
  const yy = String(now.getFullYear()).slice(-2);
  const MM = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const HH = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  return `${yy}${MM}${dd}${HH}${mm}`;
}

// ORDDAT_0 arrive en UTC ("2024-11-27T00:00:00.000Z") : on lit les composantes UTC
// pour éviter un décalage d'un jour selon le fuseau du serveur n8n.
function formatDateBC(dateValue) {
  const d = new Date(dateValue);
  const yyyy = d.getUTCFullYear();
  const MM = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${yyyy}-${MM}-${dd}`;
}

// Même référence BL pour toutes les lignes du lot
