  Array.isArray(i.json) ? i.json : [i.json]
);

// Identifiant généré UNE seule fois, partagé par tous les items
const now = new Date();
const periode = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}`;
const suffix = Math.random().toString(36).slice(2, 8).toUpperCase();
const idDA = `DA-CF-${periode}-${suffix}`;

// Un item de sortie par article, avec le même id_da
return articles.map(a => ({
  json: {
    id_da: idDA,
    ITMREF_0: a.ITMREF_0,
    ITMDES1_0: (a.ITMDES1_0 || '').trim()
  }
}));

// (accepte aussi l'ancien format [{ data: [...] }])
const rows = $input.all().flatMap(i =>
  Array.isArray(i.json.data) ? i.json.data : [i.json]
);

const groups = {};
for (const r of rows) {
  const key = [r.observation, r.marque, r.status ?? ''].join('||');

  if (!groups[key]) {
    groups[key] = {
      observation: r.observation,
      marque: r.marque,
      Demandeur: r.Demandeur,
      id_da: r.id_da,
      lignes: []
    };
    // status ajouté seulement s'il existe
    if (r.status) groups[key].status = r.status;
  }

  groups[key].lignes.push({
    code_sage: r.code_article,
    effectif: r.quantite
  });
}

// Un item par groupe => un appel API par observation
return Object.values(groups).map(g => ({
  json: {
    donnees: [g]
  }
}));
